INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('fa16fa25-b1cb-464b-a62a-cd64e26899dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "fd93b9d0-3cb3-4042-b5ba-0dda7b193707", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "bcf2f386-9fbc-4b92-b7fe-f96bb18cf80b", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "c7963f4a-fe7f-425c-bc27-5877c0695760", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "abd30acd-8ef8-4521-aad1-a238ce57536e", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "8372ea54-7b58-4e7e-8c68-c82ca796df60", "text": "Igaz", "isCorrect": true}, {"id": "7454e6b2-7ac5-40f0-90c7-29385610b631", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "86957667-f2ac-4e48-8e58-fe06c3ce75d3", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "95321a8f-924b-4804-8168-4d6ed3939cf1", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "3024e9b9-2e85-4979-aecc-972348e3cce1", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "80587873-ea80-4683-9849-f2bc570afb9c", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "affd65a2-15e5-4946-ba26-a89c57aeacfd", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "ac32af17-a8ea-4f69-98bb-8d2c323a13b2", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "9683cb72-c61f-4cac-81c4-661dc2263467", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "9f7cbdbc-8107-4baf-ac50-f5669229e9bb", "text": "Igaz", "isCorrect": true}, {"id": "80806bba-cdd4-4327-999c-fbb57c905a36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b54b25e1-5638-40b1-b687-1eae76c3565e', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f4132bb3-aa32-45f9-bc02-44c9b1349323", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bf2a2b3c-f7ff-43db-9a3e-c4581a8a99ba", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "b63a920a-8d1e-49f3-94cf-3c8dad3dd675", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "6eafe9d8-cb4d-460b-b5b6-5d765f85447c", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "00b32a2c-9ecd-4a53-ac1d-61b8a7dde651", "text": "Pontosan 5", "isCorrect": false}, {"id": "99b57f48-86d2-4197-b07a-3e951fda2dc0", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "0c7e8ff8-889c-428e-bbce-18cdced043cd", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "86712ba6-821e-487c-a9c8-cb14734438ed", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "27498c63-868a-4a08-9c83-2d926791b40a", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "4920a043-5f62-4ba0-ac4d-f33062dc37bc", "text": "Pontosan 5", "isCorrect": false}, {"id": "5c43c61b-9480-442c-898c-e75e513eb0ea", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "282f4cb4-b666-4323-8f67-baa45132a1b0", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "becc5b70-aec6-4cf4-801b-303b15c7cb1a", "text": "Igaz", "isCorrect": true}, {"id": "10742076-6cee-463f-b81d-efda08a802a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b61212c3-a08e-4d7a-b9e4-19ad9f4a00c4", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "6ff8f83c-6f88-4a68-80a4-dcc47cde825c", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "a229a129-bdf2-49d4-b07f-01e47a434003", "text": "Igaz", "isCorrect": true}, {"id": "cce92142-525d-43cc-a186-bc92d7e3e593", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bec2b1b9-f3d8-4ab9-ad69-9b0abf0fd164", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('17a4a07b-0ad7-40ef-bf96-b2cf5f2e0053', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0a0d6c46-e4ba-4cf5-bb1a-571519f37e3a", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "df189ebf-e908-4ef5-8c39-a749e4b879a1", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "503b2943-dd4c-4217-bb73-d7071d7a7429", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "31839653-7ed9-4ed9-9944-1aa7c94947dd", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "789d2288-5717-45da-b737-0081b867a075", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "440e5bd0-04cc-43d1-b729-cb34365eac31", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "45cf188b-936b-44ac-8191-0b641271c41b", "text": "Igaz", "isCorrect": true}, {"id": "73c286b6-c527-4432-9e6b-41608d73f461", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ab5bc25-28f9-40fa-ad9e-2bf965863bf9", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()),
('c3c294bc-6a0b-49f6-a981-991f9a627e43', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cac43f60-f582-492b-874b-b1010d5281be", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "4eecd493-cbe1-4a66-acd7-14c0398fecf8", "text": "1 : 3", "isCorrect": true}, {"id": "d415d323-1f73-458e-95a3-8d9363acb0ad", "text": "1 : 4", "isCorrect": false}, {"id": "acdd49d9-b42e-42cd-a360-0302fe7c279a", "text": "2 : 3", "isCorrect": false}, {"id": "f12eab12-7def-44f0-9b3e-35a8338de32e", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "8509bdd5-0905-460c-8134-b1ea8a179c79", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "4bab856d-8f27-46b2-82d8-b45ad88c583d", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "833ec067-5acc-48ff-8341-fb605f1fee82", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "182b62d5-4deb-4eb6-8149-50626de13d57", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "74bfcc42-b944-4591-a5b6-93e2445e9d8e", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "499bcefb-d094-4c41-9417-29942272a85a", "text": "Igaz", "isCorrect": true}, {"id": "7333b2d0-9911-42a5-adce-8a3eebc015c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92d72ffd-4448-4d56-b650-cb787ab45858", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW()),
('20453e94-c2af-4a2c-9c97-87c1a6241eca', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a82764ff-14a5-4559-9fcb-c196d8da446d", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "52761dce-636d-43b4-8214-1b70a6afaae9", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "943f1508-cc3b-4bc9-9f88-2727e58557b9", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "6e26ab73-c678-4155-b0db-92e304ca6ab8", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "8910fabe-6258-48fd-a639-10273ebfe034", "text": "Igaz", "isCorrect": true}, {"id": "25f14e81-3157-45d7-a31e-b3ed9a1d6e28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e7470cf6-d687-4204-bd7e-a89f0af3365d", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "d78b2f71-f221-404c-8f32-e450dde25365", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "86c5a0c3-0cd6-4f7f-925d-85887372187c", "text": "Igaz", "isCorrect": true}, {"id": "e2da0503-fc99-46e2-8bdf-7a20ab949c06", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8b6f860d-bfd3-40be-abf9-42b56de729b3", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('230279d3-f43b-4309-9109-294be7c7e1de', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e6c07ecf-09ae-4e3f-992e-33b92b7a1f21", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "c036af87-6e1a-45c0-8e90-06e64a165de2", "text": "2 : 7", "isCorrect": true}, {"id": "641dcde6-d499-48e8-ac27-33bb4ca63b38", "text": "1 : 35", "isCorrect": false}, {"id": "a0cec86f-d189-475c-8ab6-e0abe561a4b7", "text": "2 : 5", "isCorrect": false}, {"id": "aae8d847-6776-499d-b3b8-a4112d0b1a21", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "e3b8da20-2226-4dbb-82ec-75c769389a60", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "9fffcfbb-0ddc-4fad-a4eb-4432ec2e5905", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "7acc289c-f1de-4bec-8cd1-df4fd901703b", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "0685da44-0081-4290-be9b-b3d3ebfd7ec8", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "bb489f88-b386-4b9c-87a9-f2f405967585", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "e0c97abb-fe9c-4de0-8c93-c1c934aea51d", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "53260cb5-11d1-4e4b-bc74-072853b5b250", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "749e8260-73bc-4d7a-a2ff-c0e9d4fecd4a", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "37d04fd7-28d8-4b35-a764-46cdcdad8f9f", "text": "Igaz", "isCorrect": true}, {"id": "58dc6500-1d6d-40c1-aeda-b03ceddb8f26", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04fe037f-1345-4696-ba00-b23195fd4d28", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW()),
('b0d68705-24e1-43d7-979e-3b181029a889', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cc3d5a88-9a6b-4261-bd28-c2745069210f", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "0e6bac6c-1087-4e22-96ed-24e2ea0f5f9c", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "f3c52546-cb0d-4bde-8f71-983e9a15a163", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "9969a07a-9094-4134-aa8f-d2656fbfbc95", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "28836987-da41-4a33-b0fa-dea5fd24575d", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "2031f15b-f5f3-4752-b5a4-9614ba2a8eff", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "99637bd7-4002-412b-ab4c-b15dbe361d69", "text": "Igaz", "isCorrect": true}, {"id": "803aa580-5578-45ff-a978-40765e3fdeb5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "834e2bad-89c9-48b2-ad0c-85e73529e51d", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "f8b6019b-4505-4453-9445-d28133521f75", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e6c71e93-89fa-4ea4-98b3-9d64822d5258", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "de3105b8-7009-4de2-ad2d-8b05f2221045", "text": "Igaz", "isCorrect": true}, {"id": "74248f62-3793-4c51-968d-415d9974dbdd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "882609ef-ef62-431d-9f6f-31f77a9cb9a4", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "cc911494-4977-4e14-9adc-44c799e0a0e2", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('e2fa5c53-771e-4345-8119-0b630a10aff3', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c905203f-3a00-49f9-824e-7efe42ce0eb7", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "2a0828ae-f3bb-4f28-9a8f-845548824b71", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "0249fb09-f301-41d6-aa12-49a3492c7ff6", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "fa6481c9-188d-4741-bf4e-c4ee1f015f32", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "824ac747-5ec9-4bc6-a8ba-091e12d18426", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "7b20e61b-a85e-44c6-911d-880103d64dc9", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "162cdbdc-a2f0-44f9-9a1e-c82605c1e9da", "text": "Igaz", "isCorrect": true}, {"id": "64a4aa41-aa8c-44c5-82bc-f2afe53a917a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a94e180a-e8b8-44c8-b5ec-f72f0d249623", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW()),
